function Apple({phase,color,id}){return <Svg width={24} height={24} viewBox="0 0 24 24" fill={color}><Defs><Mask id={id} x={0} y={0} width={24} height={24} maskUnits="userSpaceOnUse"><Rect width={24} height={24} fill="white"/>{bites.map(([name,angle,inset])=><G key={name} {...sample('apple-bite-'+name,phase)}><Path fill="black" transform={`rotate(${angle} 12 14) translate(${inset} 0)`} d="M28 6H17Q13.5 6 13.5 8.8Q10 8.5 10.5 12Q7.8 13.3 10.5 16Q9.5 19 12.5 19.8Q13 23 17 23H28Z"/></G>)}<Rect width={24} height={24} fill="white" {...sample('apple-body-handoff',phase)}/></Mask></Defs><G transform="translate(11.3 13.6)"><G {...sample('apple-leaf-orbit',phase)}>{[['top',0,-12.8],['right',12.8,0],['bottom',0,12.8],['left',-12.8,0]].map(([name,x,y])=>{const top=name==='top',vars={'home-x':top?2.1:0,'home-y':top?-9.9:0,'home-scale':top?1:0,'leaf-x':x,'leaf-y':y,'pulse-x':x*.04,'pulse-y':y*.04,'nudge-x':x*-.025,'nudge-y':y*-.025,'morph-from':appleMorph.leaf,'morph-mid':appleCradle[name]||appleMorph.leaf,'morph-to':appleMorph[name]||appleMorph.leaf};return <G key={name} {...sample(top?'apple-leaf-travel':'apple-cradle-'+name,phase,vars)} opacity={top?1:sample('apple-leaf-appear',phase).opacity}><G {...sample('apple-leaf-pulse',phase,vars)}><Path d={top?leaf:sample('apple-cradle-'+name+'-shape',phase,vars).d} stroke={color} strokeWidth={.12}/></G></G>;})}</G></G><G origin="11.3,14.3" {...sample('apple-orbit-body',phase)}><G origin="12,14" {...sample('apple-recoil',phase)}><Path d={body} mask={`url(#${id})`}/></G>{[['one','m18.2 15.1 1.2.4-.4 1.1-1-.4Z'],['two','m3.6 11.7 1.1-.4.5 1.1-1.1.4Z'],['three','m12.6 21 .9-.5.7 1-.9.6Z']].map(([name,d])=><G key={name} {...sample('apple-crumb-'+name,phase)}><Path d={d}/></G>)}<G {...sample('apple-crumb-four',phase)}><Circle cx={11.4} cy={11} r={.45}/></G></G></Svg>;}
